fn sum_to(mut n: u64) -> u64 {
    let mut acc = 0;
    loop {                    // was: return sum_to(n - 1, acc + n)
        if n == 0 { return acc; }
        acc += n;
        n -= 1;
    }
}

#![feature(explicit_tail_calls)]
fn sum_to(n: u64, acc: u64) -> u64 {
    if n == 0 { return acc; }
    become sum_to(n - 1, acc + n);   // guaranteed tail call, constant stack
}

